SELECT AVG(is_correct::int) AS accuracy
FROM marts.fct_outcomes
WHERE split = 'test' AND arm = 'primary';

SELECT AVG(input_tokens + output_tokens) 
FROM marts.fct_requests 
WHERE setup = 'vllm' AND split = 'test';

SELECT monthly_budget_usd 
FROM marts.dim_tenant 
WHERE tenant_id = 'billing';

SELECT first_response_minutes, resolution_hours 
FROM support.sla_policies 
WHERE tenant_id = 'sales' AND priority = 'high';

SELECT COUNT(*) AS n_decisions
FROM marts.fct_outcomes
WHERE setup = 'A_tfidf' AND split = 'tune' AND arm = 'primary';

SELECT opened_at FROM support.tickets
WHERE tenant_id = 'sales' AND tenant_id NOT LIKE 'test-%'
ORDER BY opened_at LIMIT 1;

SELECT COUNT(*) 
FROM marts.fct_requests 
WHERE http_status != 200;

SELECT COUNT(*) 
FROM support.agents 
WHERE hourly_cost_usd > 6 AND is_active AND team NOT LIKE 'test-%';

SELECT COUNT(*) FROM support.tickets t
JOIN support.ticket_events e ON e.ticket_id = t.ticket_id
WHERE e.event_type = 'reopened';

SELECT sum(billed_usd) as ledger_charge
FROM marts.fct_requests
WHERE setup = 'B_local' AND split = 'test' AND arm = 'primary';
